INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A1-1', 'q1000001-0000-0000-0000-000000000001', 'Berfokus pada teknologi terbaru', 0, 'Keliru. Teknologi terbaru bukan inti dari pola pikir Value Driven.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A1-2', 'q1000001-0000-0000-0000-000000000001', 'Berfokus pada desain yang menarik', 0, 'Keliru. Desain visual hanyalah pendukung, bukan inti Value Driven.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A1-3', 'q1000001-0000-0000-0000-000000000001', 'Berfokus pada nilai yang diberikan kepada pengguna', 10, 'Tepat! Value Driven berfokus pada penciptaan nilai manfaat nyata bagi pengguna.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A1-4', 'q1000001-0000-0000-0000-000000000001', 'Berfokus pada keuntungan perusahaan', 0, 'Keliru. Keuntungan adalah hasil dari nilai yang diberikan kepada pengguna.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A10-1', 'q1000001-0000-0000-0000-000000000010', 'Membuat laporan keuangan', 0, 'Keliru. Problem Statement Canvas bukan alat akuntansi.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A10-2', 'q1000001-0000-0000-0000-000000000010', 'Merumuskan masalah secara presisi', 10, 'Tepat! Problem Statement Canvas membantu membedah dan merumuskan masalah secara terstruktur dan presisi.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A10-3', 'q1000001-0000-0000-0000-000000000010', 'Mendesain antarmuka aplikasi', 0, 'Keliru. Desain antarmuka dilakukan setelah masalah dirumuskan.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A10-4', 'q1000001-0000-0000-0000-000000000010', 'Menentukan harga produk', 0, 'Keliru. Penetapan harga bukan fungsi Problem Statement Canvas.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A2-1', 'q1000001-0000-0000-0000-000000000002', 'Fitur apa yang paling canggih?', 0, 'Keliru. Pertanyaan ini mencerminkan pola pikir feature-driven.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A2-2', 'q1000001-0000-0000-0000-000000000002', 'Teknologi apa yang paling mahal?', 0, 'Keliru. Teknologi mahal tidak menjamin solusi diterima pengguna.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A2-3', 'q1000001-0000-0000-0000-000000000002', 'Nilai apa yang dapat mempermudah hidup pengguna?', 10, 'Tepat! Mindset startup selalu berpusat pada nilai yang mempermudah hidup pengguna.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A2-4', 'q1000001-0000-0000-0000-000000000002', 'Bagaimana mengalahkan kompetitor?', 0, 'Keliru. Fokus utama adalah menyelesaikan masalah pengguna terlebih dahulu.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A3-1', 'q1000001-0000-0000-0000-000000000003', 'Mengutamakan desain modern', 0, 'Keliru. Desain modern tidak menyelesaikan akar masalah tanpa solusi nyata.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A3-2', 'q1000001-0000-0000-0000-000000000003', 'Berpegang pada masalah nyata pengguna', 10, 'Tepat! Prinsip Solve The Problem menekankan keterikatan pada masalah nyata pengguna.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A3-3', 'q1000001-0000-0000-0000-000000000003', 'Meniru kompetitor terbaik', 0, 'Keliru. Meniru kompetitor tanpa memahami masalah pengguna berisiko tidak relevan.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A3-4', 'q1000001-0000-0000-0000-000000000003', 'Mengembangkan banyak fitur', 0, 'Keliru. Banyak fitur tanpa fokus masalah justru membuat produk rumit.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A4-1', 'q1000001-0000-0000-0000-000000000004', 'Menghindari kegagalan', 0, 'Keliru. Startup agile tidak takut gagal, melainkan belajar cepat dari eksperimen.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A4-2', 'q1000001-0000-0000-0000-000000000004', 'Menunggu produk sempurna', 0, 'Keliru. Menunggu sempurna memperlambat validasi pasar.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A4-3', 'q1000001-0000-0000-0000-000000000004', 'Bergerak cepat, menerima feedback, dan terus memperbaiki produk', 10, 'Tepat! Agility berarti iterasi cepat berbasis umpan balik nyata.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A4-4', 'q1000001-0000-0000-0000-000000000004', 'Membuat produk sekali lalu selesai', 0, 'Keliru. Pengembangan produk digital bersifat berkelanjutan.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A5-1', 'q1000001-0000-0000-0000-000000000005', 'Bukti ketidakmampuan tim', 0, 'Keliru. Kegagalan awal adalah bagian dari proses pembelajaran.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A5-2', 'q1000001-0000-0000-0000-000000000005', 'Kerugian mutlak', 0, 'Keliru. Kegagalan awal justru mencegah kerugian lebih besar di masa depan.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A5-3', 'q1000001-0000-0000-0000-000000000005', 'Data berharga untuk perbaikan', 10, 'Tepat! Setiap kegagalan memberikan data validasi untuk iterasi berikutnya.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A5-4', 'q1000001-0000-0000-0000-000000000005', 'Alasan menghentikan proyek', 0, 'Keliru. Data kegagalan digunakan untuk pivot atau perbaikan, bukan menyerah.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A6-1', 'q1000001-0000-0000-0000-000000000006', 'Market Research', 0, 'Keliru. Market research adalah aktivitas riset, bukan checkpoint kesesuaian solusi.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A6-2', 'q1000001-0000-0000-0000-000000000006', 'Business Model', 0, 'Keliru. Model bisnis diskalakan setelah Problem-Solution Fit tercapai.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A6-3', 'q1000001-0000-0000-0000-000000000006', 'Problem-Solution Fit', 10, 'Tepat! Problem-Solution Fit adalah checkpoint pertama sebelum menuju Product-Market Fit.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A6-4', 'q1000001-0000-0000-0000-000000000006', 'Revenue Model', 0, 'Keliru. Checkpoint pertama berfokus pada kecocokan masalah dan solusi.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A7-1', 'q1000001-0000-0000-0000-000000000007', 'Mudah diselesaikan', 0, 'Keliru. Masalah yang mudah belum tentu dibutuhkan pasar.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A7-2', 'q1000001-0000-0000-0000-000000000007', 'Sedang tren', 0, 'Keliru. Tren bersifat sementara dan belum tentu menjadi masalah mendesak.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A7-3', 'q1000001-0000-0000-0000-000000000007', 'Mendesak dan benar-benar dialami pengguna', 10, 'Tepat! Masalah yang layak diselesaikan harus nyata dan mendesak bagi pengguna.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A7-4', 'q1000001-0000-0000-0000-000000000007', 'Disukai investor', 0, 'Keliru. Validasi utama berasal dari pengguna yang mengalami masalah.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A8-1', 'q1000001-0000-0000-0000-000000000008', 'Tampilan UI yang indah', 0, 'Keliru. Estetika UI disempurnakan setelah solusi terbukti valid.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A8-2', 'q1000001-0000-0000-0000-000000000008', 'Validasi solusi kepada pengguna', 10, 'Tepat! Prioritas utama tahap awal adalah memvalidasi apakah solusi benar-benar menjawab masalah.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A8-3', 'q1000001-0000-0000-0000-000000000008', 'Logo perusahaan', 0, 'Keliru. Identitas visual bukan prioritas validasi tahap awal.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A8-4', 'q1000001-0000-0000-0000-000000000008', 'Kampanye iklan', 0, 'Keliru. Iklan besar-besaran sebelum validasi berisiko memboroskan biaya.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A9-1', 'q1000001-0000-0000-0000-000000000009', 'Hambatan bisnis', 0, 'Keliru. Keluhan pengguna justru membuka peluang perbaikan produk.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A9-2', 'q1000001-0000-0000-0000-000000000009', 'Risiko operasional', 0, 'Keliru. Dalam mindset startup, keluhan adalah sumber wawasan inovasi.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A9-3', 'q1000001-0000-0000-0000-000000000009', 'Bahan bakar inovasi startup', 10, 'Tepat! Keluhan dan frustrasi pengguna adalah bahan bakar utama inovasi startup.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-A9-4', 'q1000001-0000-0000-0000-000000000009', 'Ancaman kompetitor', 0, 'Keliru. Keluhan pengguna membantu startup menciptakan keunggulan dibanding kompetitor.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-B1-1', 'q1000003-0000-0000-0000-000000000001', 'Data Mining', 0, 'Keliru. Data mining tidak merumuskan pain point secara langsung.');
