INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C2-1', 'q1000005-0000-0000-0000-000000000002', 'Cara pengguna mengatasi masalah saat ini', 10, 'Tepat! Alternatives menggambarkan solusi atau kebiasaan yang saat ini dipakai pengguna.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C2-2', 'q1000005-0000-0000-0000-000000000002', 'Solusi masa depan', 0, 'Keliru. Alternatives merujuk pada kondisi dan alat yang digunakan saat ini.');
