INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C3-3', 'q1000005-0000-0000-0000-000000000003', 'Kekurangan solusi yang ada saat ini', 10, 'Tepat! The Gap adalah kelemahan atau celah pada solusi alternatif yang dipakai pengguna sekarang.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C3-4', 'q1000005-0000-0000-0000-000000000003', 'Modal usaha', 0, 'Keliru. Modal usaha tidak termasuk definisi The Gap.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C4-1', 'q1000005-0000-0000-0000-000000000004', 'Target, akar masalah, dampak', 10, 'Tepat! Rumusan akhir masalah menggabungkan target pengguna, konteks, akar masalah, dan dampak.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C4-2', 'q1000005-0000-0000-0000-000000000004', 'Investor dan modal', 0, 'Keliru. Investor dan modal bukan komponen rumusan masalah pengguna.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C4-3', 'q1000005-0000-0000-0000-000000000004', 'Harga dan keuntungan', 0, 'Keliru. Harga dan keuntungan termasuk model bisnis, bukan problem statement.');
