INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C5-1', 'q1000005-0000-0000-0000-000000000005', 'Mahasiswa', 0, 'Keliru. Pada studi kasus ini, fokus masalah ada pada pengelolaan tagihan oleh pemilik kos.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C5-2', 'q1000005-0000-0000-0000-000000000005', 'Pemilik kos dengan 10-30 kamar yang tidak tinggal di lokasi kos', 10, 'Tepat! Segmen spesifiknya adalah pemilik kos 10-30 kamar yang mengelola dari jarak jauh.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C5-3', 'q1000005-0000-0000-0000-000000000005', 'Agen properti', 0, 'Keliru. Agen properti bukan target pengguna dalam studi kasus ini.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C5-4', 'q1000005-0000-0000-0000-000000000005', 'Penjaga kos', 0, 'Keliru. Target penggunanya adalah pemilik kos yang tidak tinggal di lokasi.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C6-1', 'q1000005-0000-0000-0000-000000000006', 'Sulit membangun kos baru', 0, 'Keliru. Masalahnya berkaitan dengan operasional bulanan, bukan konstruksi.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C6-2', 'q1000005-0000-0000-0000-000000000006', 'Kesulitan menagih sewa dan pencatatan masih manual', 10, 'Tepat! Penagihan dan pencatatan manual menjadi hambatan utama pemilik kos.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C6-3', 'q1000005-0000-0000-0000-000000000006', 'Biaya listrik mahal', 0, 'Keliru. Bukan biaya listrik yang menjadi fokus studi kasus.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C6-4', 'q1000005-0000-0000-0000-000000000006', 'Sulit mencari penyewa', 0, 'Keliru. Fokus kasus ini adalah pengelolaan pembayaran sewa bulanan.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C7-1', 'q1000005-0000-0000-0000-000000000007', 'Awal tahun', 0, 'Keliru. Siklus pembayaran sewa kos terjadi setiap bulan.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C7-2', 'q1000005-0000-0000-0000-000000000007', 'Pertengahan bulan', 0, 'Keliru. Puncak penagihan terjadi pada akhir bulan.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C7-3', 'q1000005-0000-0000-0000-000000000007', 'Akhir bulan', 10, 'Tepat! Masalah penagihan dan pengecekan pembayaran memuncak setiap akhir bulan.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C7-4', 'q1000005-0000-0000-0000-000000000007', 'Setiap hari', 0, 'Keliru. Konteks waktunya adalah akhir bulan saat jatuh tempo sewa.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C8-1', 'q1000005-0000-0000-0000-000000000008', 'Pendapatan meningkat', 0, 'Keliru. Keterlambatan bayar justru menghambat arus kas.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C8-2', 'q1000005-0000-0000-0000-000000000008', 'Arus kas tersendat dan memicu konflik', 10, 'Tepat! Keterlambatan pembayaran mengganggu arus kas dan berpotensi memicu konflik dengan penyewa.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C8-3', 'q1000005-0000-0000-0000-000000000008', 'Penyewa bertambah', 0, 'Keliru. Masalah penagihan tidak otomatis menambah penyewa.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C8-4', 'q1000005-0000-0000-0000-000000000008', 'Biaya internet naik', 0, 'Keliru. Dampak utamanya adalah arus kas tersendat dan potensi konflik.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C9-1', 'q1000005-0000-0000-0000-000000000009', 'ERP System', 0, 'Keliru. Pemilik kos belum menggunakan sistem terintegrasi seperti ERP.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C9-2', 'q1000005-0000-0000-0000-000000000009', 'CRM System', 0, 'Keliru. Mereka masih memakai cara manual.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C9-3', 'q1000005-0000-0000-0000-000000000009', 'Broadcast WhatsApp dan buku tulis', 10, 'Tepat! Pemilik kos mengandalkan broadcast WhatsApp untuk menagih dan buku tulis/catatan manual.');
INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES ('o1-C9-4', 'q1000005-0000-0000-0000-000000000009', 'AI Chatbot', 0, 'Keliru. Penagihan masih dilakukan secara manual lewat WhatsApp.');
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000001', 'q1000002-0000-0000-0000-000000000001', 'Value Driven adalah pola pikir startup yang berfokus pada penciptaan nilai (value) bagi pengguna dengan menyelesaikan masalah nyata yang mereka alami. Keputusan bisnis, fitur, dan inovasi dibuat berdasarkan manfaat yang diberikan kepada pengguna, bukan hanya teknologi atau keuntungan semata.', '{nilai,value,pengguna,customer,"masalah nyata",manfaat,"kebutuhan pengguna"}'::text[], '{"0": "Tidak relevan", "7": "Hanya menyebut produk disukai pelanggan", "8": "Jawaban terlalu umum", "9": "Menyebutkan manfaat bagi pengguna namun belum mengaitkan penyelesaian masalah nyata", "10": "Menjelaskan penciptaan nilai bagi pengguna dari penyelesaian masalah nyata"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000002', 'q1000002-0000-0000-0000-000000000002', 'Karena solusi dan teknologi dapat berubah, tetapi masalah pengguna tetap menjadi dasar kebutuhan pasar. Dengan memahami masalah terlebih dahulu, startup dapat menciptakan solusi yang relevan, dibutuhkan, dan memiliki peluang adopsi yang lebih tinggi.', '{"masalah pengguna","solusi bisa berubah","kebutuhan pasar",relevan,validasi}'::text[], '{"0": "Tidak relevan", "7": "Hanya menyebut teknologi bukan terpenting", "8": "Terlalu umum", "9": "Menyebutkan pemahaman kebutuhan pengguna sebelum solusi", "10": "Menjelaskan masalah sebagai dasar kebutuhan pasar & solusi relevan"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000003', 'q1000002-0000-0000-0000-000000000003', 'Agility adalah kemampuan startup untuk bergerak cepat, menerima feedback, beradaptasi terhadap perubahan, melakukan eksperimen, dan terus memperbaiki produk berdasarkan data serta kebutuhan pengguna.', '{"bergerak cepat",adaptasi,feedback,eksperimen,"perbaikan berkelanjutan"}'::text[], '{"0": "Tidak relevan", "7": "Hanya menyebut bekerja cepat", "8": "Hanya menyebut fleksibel", "9": "Menyebutkan adaptasi dan masukan pengguna", "10": "Menjelaskan bergerak cepat, adaptasi, feedback, dan eksperimen"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000004', 'q1000002-0000-0000-0000-000000000004', 'Problem-Solution Fit adalah kondisi ketika solusi yang dibuat terbukti mampu menyelesaikan masalah penting yang dialami target pengguna. Tahapan ini penting karena mengurangi risiko membangun produk yang tidak dibutuhkan pasar.', '{"solusi sesuai masalah",validasi,"kebutuhan pengguna","mengurangi risiko","dibutuhkan pasar"}'::text[], '{"0": "Tidak relevan", "7": "Hanya menyebut produk bekerja dengan baik", "8": "Terlalu umum", "9": "Menyebutkan solusi terbukti sesuai kebutuhan pengguna", "10": "Menjelaskan kecocokan solusi-masalah dan pengurangan risiko pasar"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000005', 'q1000002-0000-0000-0000-000000000005', 'Karena startup harus memastikan masalah tersebut benar-benar dialami pengguna, cukup penting untuk diselesaikan, dan layak dijadikan peluang bisnis sehingga tidak membuang waktu, biaya, dan sumber daya untuk produk yang tidak dibutuhkan.', '{"memastikan masalah nyata","kebutuhan pengguna","mengurangi risiko","efisiensi biaya",validasi}'::text[], '{"0": "Tidak relevan", "7": "Hanya menyebut urutan proses", "8": "Terlalu umum", "9": "Menyebutkan produk sesuai kebutuhan pengguna", "10": "Menjelaskan kepastian masalah nyata dan efisiensi waktu/biaya/sumber daya"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000006', 'q1000004-0000-0000-0000-000000000001', 'Keluhan pelanggan menunjukkan masalah dan hambatan yang benar-benar dialami pengguna. Data tersebut dapat menjadi sumber ide untuk menciptakan solusi baru, meningkatkan produk, atau menemukan peluang bisnis yang belum terpenuhi.', '{"keluhan pelanggan","masalah nyata","peluang inovasi","kebutuhan pengguna","perbaikan produk"}'::text[], '{"0": "Tidak relevan", "8": "Menyebutkan kebutuhan pengguna", "10": "Menyebutkan keluhan pelanggan dan perbaikan/inovasi"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000007', 'q1000004-0000-0000-0000-000000000002', 'Problem Statement Canvas adalah alat untuk mendefinisikan, menganalisis, dan memahami masalah pengguna secara terstruktur sehingga tim dapat mengidentifikasi akar masalah, dampak, konteks, serta peluang solusi.', '{"alat analisis","masalah pengguna",terstruktur,"akar masalah","peluang solusi"}'::text[], '{"0": "Tidak relevan", "8": "Menyebutkan analisis masalah umum", "10": "Menyebutkan alat analisis dan akar masalah terstruktur"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000008', 'q1000004-0000-0000-0000-000000000003', 'Empat strategi AI Prompting yaitu: 1. AI sebagai Market Researcher. 2. AI sebagai Interview Simulator. 3. AI sebagai Competitor Analyst. 4. AI sebagai Devil''s Advocate.', '{"market researcher","interview simulator","competitor analyst","devil advocate"}'::text[], '{"0": "Tidak relevan", "8": "Menjelaskan sebagian strategi", "10": "Menyebutkan keempat strategi AI Prompting"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000009', 'q1000004-0000-0000-0000-000000000004', 'Pain Point adalah keluhan atau masalah yang dirasakan pengguna, sedangkan Root Cause adalah penyebab utama yang menimbulkan masalah tersebut.', '{"pain point","gejala masalah","root cause","penyebab utama"}'::text[], '{"0": "Tidak relevan", "8": "Menjelaskan salah satunya", "10": "Menjelaskan perbedaan pain point dan root cause"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000010', 'q1000004-0000-0000-0000-000000000005', 'Karena tidak semua orang mengalami masalah yang sama. Target yang terlalu luas membuat solusi sulit fokus, sedangkan segmentasi yang spesifik membantu validasi dan pengembangan solusi yang lebih tepat.', '{segmentasi,spesifik,fokus,"kebutuhan berbeda","target pengguna"}'::text[], '{"0": "Tidak relevan", "8": "Menjelaskan target pasar", "10": "Menjelaskan alasan segmentasi dan kebutuhan yang berbeda"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000011', 'q1000006-0000-0000-0000-000000000001', '5 Whys adalah metode menemukan akar masalah dengan mengajukan pertanyaan "Mengapa?" secara berulang hingga ditemukan penyebab paling mendasar dari suatu masalah.', '{"5 whys",mengapa,"akar masalah",berulang,penyebab}'::text[], '{"0": "Tidak relevan", "8": "Menjelaskan mencari penyebab masalah", "10": "Menjelaskan metode 5 Whys dengan bertanya mengapa berulang untuk menemukan akar masalah"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000012', 'q1000006-0000-0000-0000-000000000002', 'The Gap adalah kekurangan atau kelemahan dari solusi yang saat ini digunakan pengguna. Gap ditemukan dengan membandingkan kebutuhan pengguna terhadap kemampuan solusi yang sudah ada.', '{gap,"kelemahan solusi","kebutuhan pengguna","peluang inovasi",kekurangan}'::text[], '{"0": "Tidak relevan", "8": "Menjelaskan kekurangan produk kompetitor", "10": "Menjelaskan definisi The Gap dan cara menemukannya dari perbandingan kebutuhan & solusi ada"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000013', 'q1000006-0000-0000-0000-000000000003', 'Contoh: "Pemilik kos dengan 10-30 kamar kesulitan mengelola pembayaran sewa pada akhir bulan karena proses pencatatan dan pengecekan pembayaran masih manual, yang mengakibatkan keterlambatan pembayaran, konflik dengan penyewa, dan arus kas yang terganggu."', '{kesulitan,saat,karena,mengakibatkan,berakibat,manual,"akhir bulan"}'::text[], '{"0": "Tidak relevan", "8": "Memuat sebagian komponen format", "10": "Memuat seluruh elemen format: Target, Konteks, Akar Masalah, dan Dampak"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000014', 'q1000006-0000-0000-0000-000000000004', 'Peluang inovasi yang dapat dibuat adalah sistem manajemen kos digital yang menyediakan pengingat otomatis, verifikasi pembayaran otomatis, dashboard keuangan, dan laporan real-time sehingga mengurangi pekerjaan manual serta keterlambatan pembayaran.', '{"manajemen kos digital",otomatisasi,pembayaran,dashboard,efisiensi,"pengingat otomatis"}'::text[], '{"0": "Tidak relevan", "8": "Menyebutkan aplikasi kos secara umum", "10": "Menganalisis masalah kos dan menyebutkan solusi otomatisasi/dashboard/pembayaran"}'::jsonb);
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES ('er-0000001-0000-0000-0000-000000000015', 'q1000006-0000-0000-0000-000000000005', 'Feedback pengguna penting karena membantu startup memahami kebutuhan pasar, menemukan kekurangan produk, memvalidasi asumsi, mengurangi risiko kegagalan, dan meningkatkan kualitas solusi secara berkelanjutan.', '{feedback,"kebutuhan pasar",validasi,"perbaikan produk","mengurangi risiko"}'::text[], '{"0": "Tidak relevan", "8": "Menjelaskan feedback untuk memperbaiki aplikasi", "10": "Menjelaskan peran feedback untuk validasi, perbaikan produk, dan mengurangi risiko"}'::jsonb);
